    comp:[["Where does the boys' plane crash?",["In the sea","On a tropical island","In a city","In the mountains"],1,"It crashes on a tropical island."],["Why are there no adults on the island?",["They stayed on the plane","None of them survived the crash","They went exploring alone","They flew home again"],1,"No adult survives the crash."],["What does the fat boy with glasses ask Ralph not to call him?",["Ralph","Fatty","Piggy","Jack"],2,"He hates the nickname Piggy."],["What object do Ralph and Piggy find near the beach?",["A knife","A conch shell","A small boat","A map"],1,"They find a large conch shell."],["What happens when Ralph blows the conch?",["Nothing happens at all","Boys come from all over the island","The plane starts again","The shell breaks"],1,"Its sound calls the other boys together."],["Who leads the group of boys in black cloaks?",["Ralph","Piggy","Jack Merridew","Simon"],2,"Jack Merridew leads the choir."],["Who do the boys choose as their chief?",["Jack","Piggy","Ralph","Simon"],2,"Most boys vote for Ralph."],["What happens when Jack finds a trapped piglet?",["He kills it at once","He cannot bring himself to kill it","He sets it free happily","He feeds it fruit"],1,"He raises his knife but cannot strike."]],
